# Build src-tauri/icons/icon.ico the way Windows expects: uncompressed 32-bit bitmap frames for the
# small sizes (16-64 px) and a PNG frame only for 256 px. Icons whose small frames are PNG-compressed
# can show up as a generic icon in Start, Search and the shell icon cache.
#
#   powershell -ExecutionPolicy Bypass -File scripts/make-ico.ps1
#
# Source: src-tauri/icons/icon.png (generated by `npm run icons` from assets/brand/velora-icon.svg).

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Drawing

$root = Split-Path -Parent $PSScriptRoot
$src = Join-Path $root "src-tauri\icons\icon.png"
$dst = Join-Path $root "src-tauri\icons\icon.ico"
$sizes = 16, 20, 24, 32, 40, 48, 64, 256

$source = [System.Drawing.Image]::FromFile($src)

function Render([int]$size) {
    $bmp = New-Object System.Drawing.Bitmap $size, $size, ([System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.InterpolationMode = "HighQualityBicubic"
    $g.SmoothingMode = "HighQuality"
    $g.PixelOffsetMode = "HighQuality"
    $g.CompositingQuality = "HighQuality"
    $g.Clear([System.Drawing.Color]::Transparent)
    $g.DrawImage($source, 0, 0, $size, $size)
    $g.Dispose()
    return $bmp
}

# A DIB frame: BITMAPINFOHEADER (height doubled for the AND mask), bottom-up BGRA pixels, AND mask.
function DibFrame([System.Drawing.Bitmap]$bmp) {
    $s = $bmp.Width
    $ms = New-Object System.IO.MemoryStream
    $w = New-Object System.IO.BinaryWriter $ms
    $w.Write([UInt32]40); $w.Write([Int32]$s); $w.Write([Int32]($s * 2)); $w.Write([UInt16]1); $w.Write([UInt16]32)
    $w.Write([UInt32]0); $w.Write([UInt32]($s * $s * 4)); $w.Write([Int32]0); $w.Write([Int32]0); $w.Write([UInt32]0); $w.Write([UInt32]0)
    for ($y = $s - 1; $y -ge 0; $y--) {
        for ($x = 0; $x -lt $s; $x++) {
            $c = $bmp.GetPixel($x, $y)
            $w.Write([byte]$c.B); $w.Write([byte]$c.G); $w.Write([byte]$c.R); $w.Write([byte]$c.A)
        }
    }
    $maskStride = [int]([Math]::Ceiling($s / 32.0) * 4)
    $w.Write((New-Object byte[] ($maskStride * $s)))  # all zero: alpha channel decides transparency
    $w.Flush()
    # The leading comma stops PowerShell from unrolling the byte array into separate objects.
    return , $ms.ToArray()
}

function PngFrame([System.Drawing.Bitmap]$bmp) {
    $ms = New-Object System.IO.MemoryStream
    $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
    return , $ms.ToArray()
}

$frames = foreach ($s in $sizes) {
    $bmp = Render $s
    [byte[]]$data = if ($s -ge 256) { PngFrame $bmp } else { DibFrame $bmp }
    $bmp.Dispose()
    [pscustomobject]@{ Size = $s; Data = $data }
}
$source.Dispose()

$out = New-Object System.IO.MemoryStream
$w = New-Object System.IO.BinaryWriter $out
$w.Write([UInt16]0); $w.Write([UInt16]1); $w.Write([UInt16]$frames.Count)
$offset = 6 + 16 * $frames.Count
foreach ($f in $frames) {
    $dim = if ($f.Size -ge 256) { 0 } else { $f.Size }
    $w.Write([byte]$dim); $w.Write([byte]$dim); $w.Write([byte]0); $w.Write([byte]0)
    $w.Write([UInt16]1); $w.Write([UInt16]32); $w.Write([UInt32]$f.Data.Length); $w.Write([UInt32]$offset)
    $offset += $f.Data.Length
}
foreach ($f in $frames) { $w.Write($f.Data) }
$w.Flush()
[System.IO.File]::WriteAllBytes($dst, $out.ToArray())
"Wrote $dst with sizes: $($sizes -join ', ')"
